glob member_edges: dict[str, list[str]] = {};
glob channel_post_edges: dict[str, list[str]] = {};
glob counter: dict[str, int] = {"n": 0};

def reset_store -> None {
    accounts.clear();
    current["user"] = "";
    profiles.clear();
    tweets.clear();
    channels.clear();
    follow_edges.clear();
    post_edges.clear();
    member_edges.clear();
    channel_post_edges.clear();
    counter["n"] = 0;
}

def next_id(prefix: str) -> str {
    counter["n"] = counter["n"] + 1;
    return prefix + str(counter["n"]);
}

def register_user(username: str, password: str) -> bool {
    if username in accounts {
        return False;
    }
    accounts[username] = password;
    return True;
}

def login(username: str, password: str) -> bool {
    if username in accounts {
        if accounts[username] == password {
            current["user"] = username;
            return True;
        }
    }
    return False;
}

def setup_profile(username: str, bio: str) -> dict {
    user = current["user"];
    if user == "" {
        return {};
    }
    if user not in profiles {
        profiles[user] = {"_jac_id": next_id("p"), "username": "", "bio": ""};
    }
    if username {
        profiles[user]["username"] = username;
    }
    if bio {
        profiles[user]["bio"] = bio;
    }
    tweet_rows: list = [];
    ids: list = [];
    if user in post_edges {
        ids = post_edges[user];
    }
    i = 0;
    while i < len(ids) {
        tweet_rows.append(tweets[ids[i]]);
        i = i + 1;
    }
    following_rows: list = [];
    fids: list = [];
    if user in follow_edges {
        fids = follow_edges[user];
    }
    i = 0;
    while i < len(fids) {
        following_rows.append(profiles[fids[i]]);
        i = i + 1;
    }
    return {"profile": profiles[user], "tweets": tweet_rows, "following": following_rows};
}

def get_profile -> dict {
    return setup_profile("", "");
}

def create_tweet(content: str) -> dict {
    user = current["user"];
    if user == "" {
        return {};
    }
    tid = next_id("t");
    row = {
        "_jac_id": tid,
        "content": content,
        "author_username": profiles[user]["username"],
        "likes": [],
        "comments": []
    };
    tweets[tid] = row;
    lst: list = [];
    if user in post_edges {
        lst = post_edges[user];
    }
    lst.append(tid);
    post_edges[user] = lst;
    return row;
}

def like_tweet(tweet_id: str) -> dict {
    user = current["user"];
    actor = profiles[user]["username"];
    likes = tweets[tweet_id]["likes"];
    already = False;
    i = 0;
    while i < len(likes) {
        if likes[i] == actor {
            already = True;
        }
        i = i + 1;
    }
    if already {
        kept: list = [];
        i = 0;
        while i < len(likes) {
            if likes[i] != actor {
                kept.append(likes[i]);
            }
            i = i + 1;
        }
        tweets[tweet_id]["likes"] = kept;
        return {"liked": False, "likes": kept};
    }
    likes.append(actor);
    tweets[tweet_id]["likes"] = likes;
    return {"liked": True, "likes": likes};
}

def add_comment(tweet_id: str, content: str) -> dict {
    user = current["user"];
    comment = {"username": profiles[user]["username"], "content": content};
    lst = tweets[tweet_id]["comments"];
    lst.append(comment);
    tweets[tweet_id]["comments"] = lst;
    return {"success": True, "comment": comment};
}

def delete_tweet(tweet_id: str) -> dict {
    user = current["user"];
    if tweet_id in tweets {
        if tweets[tweet_id]["author_username"] == profiles[user]["username"] {
            del tweets[tweet_id];
            for u in post_edges.keys() {
                kept: list = [];
                lst = post_edges[u];
                i = 0;
                while i < len(lst) {
                    if lst[i] != tweet_id {
                        kept.append(lst[i]);
                    }
                    i = i + 1;
                }
                post_edges[u] = kept;
            }
            return {"success": True};
        }
    }
    return {"success": False};
}

def follow_user(target_id: str) -> dict {
    user = current["user"];
    target = "";
    for u in profiles.keys() {
        if profiles[u]["_jac_id"] == target_id {
            target = u;
        }
    }
    if target == "" {
        return {"success": False};
    }
    lst: list = [];
    if user in follow_edges {
        lst = follow_edges[user];
    }
    lst.append(target);
    follow_edges[user] = lst;
    return {"success": True};
}

def unfollow_user(target_id: str) -> dict {
    user = current["user"];
    target = "";
    for u in profiles.keys() {
        if profiles[u]["_jac_id"] == target_id {
            target = u;
        }
    }
    if target == "" {
        return {"success": False};
    }
    kept: list = [];
    lst: list = [];
    if user in follow_edges {
        lst = follow_edges[user];
    }
    i = 0;
    while i < len(lst) {
        if lst[i] != target {
            kept.append(lst[i]);
        }
        i = i + 1;
    }
    follow_edges[user] = kept;
    return {"success": True};
}

def load_feed(search_query: str) -> list {
    user = current["user"];
    queue: list = [user];
    seen: list = [];
    rows: list = [];
    while len(queue) > 0 {
        cur = queue.pop(0);
        dup = False;
        i = 0;
        while i < len(seen) {
            if seen[i] == cur {
                dup = True;
            }
            i = i + 1;
        }
        if dup {
            continue;
        }
        seen.append(cur);
        ids: list = [];
        if cur in post_edges {
            ids = post_edges[cur];
        }
        i = 0;
        while i < len(ids) {
            rows.append(tweets[ids[i]]);
            i = i + 1;
        }
        if cur == user {
            fids: list = [];
            if user in follow_edges {
                fids = follow_edges[user];
            }
            i = 0;
            while i < len(fids) {
                queue.append(fids[i]);
                i = i + 1;
            }
        }
    }
    if search_query {
        q = search_query.lower().strip();
        kept: list = [];
        i = 0;
        while i < len(rows) {
            if q in rows[i]["content"].lower() {
                kept.append(rows[i]);
            }
            i = i + 1;
        }
        rows = kept;
    }
    return rows;
}

def get_trending -> list {
    counts: dict = {};
    for tid in tweets.keys() {
        words = tweets[tid]["content"].split();
        i = 0;
        while i < len(words) {
            word = words[i];
            i = i + 1;
            if word.startswith("#") and len(word) > 1 {
                tag = word.lower().rstrip(".,!?;:");
                if tag in counts {
                    counts[tag] = counts[tag] + 1;
                } else {
                    counts[tag] = 1;
                }
            }
        }
    }
    rows: list = [];
    for tag in counts.keys() {
        rows.append({"tag": tag, "count": counts[tag]});
    }
    return rows;
}

def get_all_profiles -> list {
    rows: list = [];
    for u in profiles.keys() {
        rows.append(profiles[u]);
    }
    return rows;
}

def create_channel(name: str, description: str) -> dict {
    user = current["user"];
    cid = next_id("c");
    channels[cid] = {"_jac_id": cid, "name": name, "description": description};
    lst: list = [];
    if user in member_edges {
        lst = member_edges[user];
    }
    lst.append(cid);
    member_edges[user] = lst;
    return channel_detail(cid);
}

def member_count_of(cid: str) -> int {
    n = 0;
    for u in member_edges.keys() {
        lst = member_edges[u];
        i = 0;
        while i < len(lst) {
            if lst[i] == cid {
                n = n + 1;
            }
            i = i + 1;
        }
    }
    return n;
}

def channel_detail(cid: str) -> dict {
    user = current["user"];
    mine: list = [];
    if user in member_edges {
        mine = member_edges[user];
    }
    is_member = False;
    i = 0;
    while i < len(mine) {
        if mine[i] == cid {
            is_member = True;
        }
        i = i + 1;
    }
    posts: list = [];
    ids: list = [];
    if cid in channel_post_edges {
        ids = channel_post_edges[cid];
    }
    i = 0;
    while i < len(ids) {
        posts.append(tweets[ids[i]]);
        i = i + 1;
    }
    return {
        "channel": channels[cid],
        "member_count": member_count_of(cid),
        "is_member": is_member,
        "posts": posts
    };
}

def join_channel(cid: str) -> dict {
    user = current["user"];
    lst: list = [];
    if user in member_edges {
        lst = member_edges[user];
    }
    already = False;
    i = 0;
    while i < len(lst) {
        if lst[i] == cid {
            already = True;
        }
        i = i + 1;
    }
    if already == False {
        lst.append(cid);
        member_edges[user] = lst;
    }
    return {"success": True};
}

def create_channel_tweet(cid: str, content: str) -> dict {
    user = current["user"];
    tid = next_id("t");
    tweets[tid] = {
        "_jac_id": tid,
        "content": content,
        "author_username": profiles[user]["username"],
        "likes": [],
        "comments": []
    };
    lst: list = [];
    if cid in channel_post_edges {
        lst = channel_post_edges[cid];
    }
    lst.append(tid);
    channel_post_edges[cid] = lst;
    return tweets[tid];
}

