# Edges are stored as adjacency lists of {"to", "label"} records;
# node kinds live in a separate id -> kind map.

def forward(edges: dict[str, list[dict]], src: str) -> list[str] {
    # All forward connections
    return [e["to"] for e in edges.get(src, [])];
}

def backward(edges: dict[str, list[dict]], dst: str) -> list[str] {
    # All backward connections
    result: list[str] = [];
    for src in edges {
        for e in edges[src] {
            if e["to"] == dst {
                result.append(src);
            }
        }
    }
    return result;
}

def both_dirs(edges: dict[str, list[dict]], nid: str) -> list[str] {
    # Both directions
    return forward(edges, nid) + backward(edges, nid);
}

def forward_kind(edges: dict[str, list[dict]], kinds: dict[str, str], src: str, kind: str) -> list[str] {
    # Only ids of a given kind
    return [n for n in forward(edges, src) if kinds.get(n, "") == kind];
}

def forward_via(edges: dict[str, list[dict]], src: str, label: str) -> list[str] {
    # Only via edges with a given label
    return [e["to"] for e in edges.get(src, []) if e["label"] == label];
}

def friends_of_friends(edges: dict[str, list[dict]], src: str) -> list[str] {
    # Chained traversal: two "knows" hops
    result: list[str] = [];
    for mid in forward_via(edges, src, "knows") {
        for far in forward_via(edges, mid, "knows") {
            result.append(far);
        }
    }
    return result;
}

