"""
Python-Jac AST linking, rewritten without the pass/visitor machinery.

Both ASTs are flat dict stores keyed by id: each Jac node is a dict record
with a "kind" tag and a child adjacency list, and each Python node is a dict
record. Linking establishes bidirectional maps between the two by:

1. Recording connections where multiple Jac nodes map to a single Python node
2. Handling special cases like abilities where params must correspond between
   the declaration and the implementation
3. Resolving names across the AST boundary (an archetype also links its name
   child to the Python ClassDef)

The traversal is a plain post-order walk over the child adjacency map with a
per-kind dispatch, instead of exit_* methods on a pass object.
"""

glob jac_nodes: dict[str, dict] = {};
glob jac_children: dict[str, list[str]] = {};
glob py_nodes: dict[str, dict] = {};
glob jac_to_py: dict[str, list[str]] = {};
glob py_to_jac: dict[str, str] = {};

def add_jac_node(nid: str, kind: str, name: str, py_ids: list[str]) -> None {
    jac_nodes[nid] = {"kind": kind, "name": name, "py": py_ids};
    jac_children[nid] = [];
}

def add_jac_child(parent_id: str, child_id: str) -> None {
    jac_children[parent_id].append(child_id);
}

def add_py_node(pid: str, kind: str, name: str) -> None {
    py_nodes[pid] = {"kind": kind, "name": name};
}

def link_jac_py_nodes(jac_id: str, py_ids: list[str]) -> None {
    if jac_id not in jac_to_py {
        jac_to_py[jac_id] = [];
    }
    i = 0;
    while i < len(py_ids) {
        pid = py_ids[i];
        jac_to_py[jac_id].append(pid);
        py_to_jac[pid] = jac_id;
        i = i + 1;
    }
}

def link_self(nid: str) -> None {
    link_jac_py_nodes(nid, jac_nodes[nid]["py"]);
}

def link_name_child(nid: str) -> None {
    # Name-resolution across the boundary: the first name child of an
    # archetype/enum/ability shares its parent's Python node.
    kids = jac_children.get(nid, []);
    i = 0;
    while i < len(kids) {
        kid = kids[i];
        if jac_nodes[kid]["kind"] == "name" {
            link_jac_py_nodes(kid, jac_nodes[nid]["py"]);
            return;
        }
        i = i + 1;
    }
}

def link_params(nid: str) -> None {
    # Parameter correspondence: each param_var child links to the matching
    # positional Python arg of the enclosing function's Python node.
    fn_py = jac_nodes[nid]["py"];
    if len(fn_py) == 0 {
        return;
    }
    kids = jac_children.get(nid, []);
    pos = 0;
    i = 0;
    while i < len(kids) {
        kid = kids[i];
        if jac_nodes[kid]["kind"] == "param_var" {
            link_jac_py_nodes(kid, [fn_py[0] + ".args[" + str(pos) + "]"]);
            pos = pos + 1;
        }
        i = i + 1;
    }
}

def link_impl_to_decl(nid: str) -> None {
    # An impl_def shares the Python nodes of the declaration it implements.
    impl_name = jac_nodes[nid]["name"];
    for other_id in jac_nodes.keys() {
        other = jac_nodes[other_id];
        if other["kind"] == "ability" and other["name"] == impl_name {
            link_jac_py_nodes(nid, other["py"]);
            return;
        }
    }
}

def dispatch_exit(nid: str) -> None {
    kind = jac_nodes[nid]["kind"];
    if kind == "module_path" {
        link_self(nid);
    } elif kind == "type_alias" {
        link_self(nid);
        link_name_child(nid);
    } elif kind == "archetype" or kind == "enum" {
        link_self(nid);
        link_name_child(nid);
    } elif kind == "ability" {
        link_self(nid);
        link_name_child(nid);
        link_params(nid);
    } elif kind == "impl_def" {
        link_impl_to_decl(nid);
        link_params(nid);
    } elif kind == "param_var" {
        if len(jac_nodes[nid]["py"]) > 0 {
            link_self(nid);
        }
    } elif kind == "except" or kind == "expr_as_item" {
        link_self(nid);
        link_name_child(nid);
    } elif kind == "global_stmt" or kind == "non_local_stmt" {
        link_self(nid);
    } elif kind == "k_w_pair" or kind == "atom_trailer" {
        link_self(nid);
    }
}

def run_link_pass(root_id: str) -> None {
    # Pre-order collect, then replay reversed for post-order (exit) semantics.
    order: list[str] = [];
    stack: list[str] = [root_id];
    while len(stack) > 0 {
        cur = stack.pop();
        order.append(cur);
        kids = jac_children.get(cur, []);
        i = 0;
        while i < len(kids) {
            stack.append(kids[i]);
            i = i + 1;
        }
    }
    j = len(order) - 1;
    while j >= 0 {
        dispatch_exit(order[j]);
        j = j - 1;
    }
}

