rebuild function assembles the kid adjacency list from those fields in
pre-order over the tree. This runs before consumers that read the kid lists
(e.g. doc-IR generation). Kinds absent from the table fall back to their
field insertion order.
"""

glob nodes: dict[str, dict] = {};
glob kids: dict[str, list[str]] = {};

glob kid_order: dict[str, list[str]] = {
    "module": ["doc", "body"],
    "sub_tag": ["tag"],
    "type_alias": ["name", "type_params", "value"],
    "type_param": ["name", "bound"],
    "global_vars": ["access", "assignments"],
    "test": ["name", "body"],
    "module_code": ["name", "body"],
    "client_block": ["body"],
    "server_block": ["body"],
    "native_block": ["body"],
    "py_inline_code": ["code"],
    "import": ["from_loc", "paths", "items"],
    "module_path": ["path", "alias"],
    "module_item": ["name", "alias"],
    "archetype": ["decorators", "name", "base_classes", "body"],
    "impl_def": ["target", "spec", "body"],
    "enum": ["decorators", "name", "base_classes", "body"],
    "ability": ["decorators", "name", "signature", "body"],
    "func_signature": ["params", "return_type"],
    "event_signature": ["event", "arch_tag"],
    "param_var": ["name", "type_tag", "value"],
    "arch_has": ["access", "vars"],
    "has_var": ["name", "type_tag", "value"],
    "if_stmt": ["condition", "body", "else_body"],
    "else_if": ["condition", "body", "else_body"],
    "else_stmt": ["body"],
    "expr_stmt": ["expr"],
    "try_stmt": ["body", "excepts", "else_body", "finally_body"],
    "except": ["ex_type", "name", "body"],
    "finally_stmt": ["body"],
    "iter_for_stmt": ["iter", "condition", "count_by", "body"],
    "in_for_stmt": ["target", "collection", "body"],
    "while_stmt": ["condition", "body"],
    "with_stmt": ["exprs", "body"],
    "expr_as_item": ["expr", "alias"],
    "raise_stmt": ["cause", "from_target"],
    "assert_stmt": ["condition", "error_msg"],
    "return_stmt": ["expr"],
    "assignment": ["target", "type_tag", "value"],
    "binary_expr": ["left", "op", "right"],
    "compare_expr": ["left", "ops", "rights"],
    "bool_expr": ["values"],
    "lambda_expr": ["signature", "body"],
    "unary_expr": ["op", "operand"],
    "if_else_expr": ["value", "condition", "else_value"],
    "f_string": ["parts"],
    "formatted_value": ["expr", "format_spec"],
    "list_val": ["values"],
    "set_val": ["values"],
    "tuple_val": ["values"],
    "dict_val": ["kv_pairs"],
    "k_v_pair": ["key", "value"],
    "k_w_pair": ["key", "value"],
    "inner_compr": ["target", "collection", "conditional"],
    "list_compr": ["out_expr", "compr"],
    "dict_compr": ["kv_pair", "compr"],
    "atom_trailer": ["target", "right"],
    "atom_unit": ["value"],
    "yield_expr": ["expr"],
    "func_call": ["target", "params"],
    "index_slice": ["target", "slices"],
    "match_stmt": ["target", "cases"],
    "match_case": ["pattern", "guard", "body"],
    "switch_stmt": ["target", "cases"],
    "switch_case": ["values", "body"]
};

def add_ast_node(nid: str, kind: str, fields: dict[str, list[str]]) -> None {
    nodes[nid] = {"kind": kind, "fields": fields};
}

def rebuild_kids(nid: str) -> None {
    rec = nodes[nid];
    fields = rec["fields"];
    order = kid_order.get(rec["kind"], []);
    if len(order) == 0 {
        order = list(fields.keys());
    }
    rebuilt: list[str] = [];
    i = 0;
    while i < len(order) {
        field_kids = fields.get(order[i], []);
        j = 0;
        while j < len(field_kids) {
            rebuilt.append(field_kids[j]);
            j = j + 1;
        }
        i = i + 1;
    }
    kids[nid] = rebuilt;
}

def run_normalize(root_id: str) -> None {
    stack: list[str] = [root_id];
    while len(stack) > 0 {
        cur = stack.pop();
        rebuild_kids(cur);
        rebuilt = kids[cur];
        i = 0;
        while i < len(rebuilt) {
            stack.append(rebuilt[i]);
            i = i + 1;
        }
    }
}

with entry {
    add_ast_node("m", "module", {"doc": ["doc1"], "body": ["abl"]});
    add_ast_node("doc1", "token", {});
    add_ast_node("abl", "ability", {
        "body": ["ret"],
        "signature": ["sig"],
        "name": ["abl_name"],
        "decorators": []
    });
    add_ast_node("abl_name", "token", {});
    add_ast_node("sig", "func_signature", {"return_type": ["rt"], "params": ["p1", "p2"]});
    add_ast_node("p1", "param_var", {"name": ["p1n"], "type_tag": ["p1t"]});
    add_ast_node("p1n", "token", {});
    add_ast_node("p1t", "token", {});
    add_ast_node("p2", "param_var", {"name": ["p2n"], "type_tag": ["p2t"]});
    add_ast_node("p2n", "token", {});
    add_ast_node("p2t", "token", {});
    add_ast_node("rt", "token", {});
    add_ast_node("ret", "return_stmt", {"expr": ["add"]});
    add_ast_node("add", "binary_expr", {"right": ["rhs"], "left": ["lhs"], "op": ["plus"]});
    add_ast_node("lhs", "token", {});
    add_ast_node("plus", "token", {});
    add_ast_node("rhs", "token", {});

    run_normalize("m");

    for nid in ["m", "abl", "sig", "p1", "ret", "add"] {
        rebuilt = kids[nid];
        print(f"{nid}: {rebuilt}");
    }
}

