glob city_vals: dict[str, int] = {};
glob city_edges: dict[str, list[dict]] = {};

def add_city(cid: str, val: int) -> None {
    city_vals[cid] = val;
}

def connect(src: str, dst: str, edge_kind: str) -> None {
    if src not in city_edges {
        city_edges[src] = [];
    }
    city_edges[src].append({"to": dst, "kind": edge_kind});
}

def route(start_id: str) -> dict[str, list] {
    seen: list[int] = [];
    stack: list[str] = [start_id];
    while len(stack) > 0 {
        cur = stack.pop(0);
        seen.append(city_vals[cur]);
        outgoing = city_edges.get(cur, []);
        i = 0;
        while i < len(outgoing) {
            entry_rec = outgoing[i];
            if entry_rec["kind"] == "Road" {
                stack.append(entry_rec["to"]);
            }
            i = i + 1;
        }
    }
    return {"seen": seen};
}

