"""Subtype + tuple trigger dispatch fixture: records are dicts tagged with a
"kind" field, the subtype relation is an explicit parents map checked by a
plain is_a function, and the two triggered handlers are guarded branches in a
dispatch function over a mutable state dict. Dispatching on Sub(5) then
Other(7):
  - the Base-triggered branch fires only on Sub (subtype-aware) -> base = 5
  - the (Sub, Other)-triggered branch fires on both             -> either = 12
"""

glob parents: dict[str, list[str]] = {
    "Base": [],
    "Sub": ["Base"],
    "Other": []
};

def is_a(kind: str, target: str) -> bool {
    frontier: list[str] = [kind];
    while len(frontier) > 0 {
        cur = frontier.pop();
        if cur == target {
            return True;
        }
        supers = parents.get(cur, []);
        i = 0;
        while i < len(supers) {
            frontier.append(supers[i]);
            i = i + 1;
        }
    }
    return False;
}

def matches_any(kind: str, targets: list[str]) -> bool {
    i = 0;
    while i < len(targets) {
        if is_a(kind, targets[i]) {
            return True;
        }
        i = i + 1;
    }
    return False;
}

def dispatch(state: dict, rec: dict) -> None {
    if is_a(rec["kind"], "Base") {
        state["base"] = state["base"] + rec["val"];
    }
    if matches_any(rec["kind"], ["Sub", "Other"]) {
        state["either"] = state["either"] + rec["val"];
    }
}

def subtype_dispatch_run() -> dict[str, int] {
    state = {"base": 0, "either": 0};
    dispatch(state, {"kind": "Sub", "val": 5});
    dispatch(state, {"kind": "Other", "val": 7});
    return {"base": state["base"], "either": state["either"]};
}

