glob scopes: dict[str, dict] = {};
glob scope_kids: dict[str, list[str]] = {};
glob scope_parent: dict[str, str] = {};
glob scope_stack: list[str] = [];

# scope kinds that are real Python scopes (module/ability); block scopes are not
glob PY_SCOPES: list[str] = ["module", "ability", "archetype", "lambda", "compr"];

def make_scope(sid: str, name: str, kind: str) -> str {
    scopes[sid] = {"name": name, "kind": kind, "names_in_scope": {}};
    scope_kids[sid] = [];
    scope_parent[sid] = "";
    return sid;
}

def cur_scope() -> str {
    return scope_stack[len(scope_stack) - 1];
}

def push_scope_and_link(sid: str) -> None {
    if len(scope_stack) > 0 {
        parent = cur_scope();
        scope_kids[parent].append(sid);
        scope_parent[sid] = parent;
    }
    scope_stack.append(sid);
}

def pop_scope() -> str {
    return scope_stack.pop();
}

def insert_symbol(sid: str, name: str, kind: str) -> None {
    scopes[sid]["names_in_scope"][name] = {"kind": kind, "defns": 1};
