def find_python_scope_node_of(sid: str) -> str {
    cur = sid;
    while cur != "" {
        if str(scopes[cur]["kind"]) in PY_SCOPES {
            return cur;
        }
        cur = scope_parent[cur];
    }
    return "";
}

