"""Construct helpers rewritten over a dict graph: node connections and the
depth-bounded traversal run on a dict-of-lists adjacency map, no archetypes."""

import os;

# node_id -> list of {"to": id, "edge_type": name, "edge_id": id}
glob adjacency: dict[str, list[dict]] = {};

def add_conn(src: str, tgt: str, edge_type: str, edge_id: str) -> None {
    if src not in adjacency {
        adjacency[src] = [];
    }
    if tgt not in adjacency {
        adjacency[tgt] = [];
    }
    adjacency[src].append({"to": tgt, "edge_type": edge_type, "edge_id": edge_id});
}

"""Collect every (src, edge, tgt) connection reachable from a node, with an
explicit stack instead of recursion over node objects."""
def collect_node_connections(start_id: str, visited: list[str], connections: list[tuple], edge_ids: list[str]) -> None {
    stack: list[str] = [start_id];
    while len(stack) > 0 {
        cur = stack.pop();
        if cur in visited {
            continue;
        }
        visited.append(cur);
        for e in adjacency.get(cur, []) {
            if str(e["edge_id"]) not in edge_ids {
                edge_ids.append(str(e["edge_id"]));
                connections.append((cur, str(e["edge_type"]), str(e["to"])));
            }
            stack.append(str(e["to"]));
        }
    }
}

"""BFS/DFS traversal with depth bound, edge-type filter, and node/edge caps."""
def traverse_graph(
    start_id: str,
    depth: int,
    edge_type: list[str],
    bfs: bool,
    node_limit: int,
    edge_limit: int
) -> dict {
    connections: list[tuple] = [];
    node_depths: dict[str, int] = {start_id: 0};
    visited: list[str] = [];
    frontier: list[str] = [start_id];
    n_edges = 0;
    while len(frontier) > 0 and len(visited) < node_limit {
        if bfs {
            cur = frontier.pop(0);
        } else {
            cur = frontier.pop();
        }
        if cur in visited {
            continue;
        }
        visited.append(cur);
        cur_depth = int(str(node_depths[cur]));
        if depth >= 0 and cur_depth >= depth {
            continue;
        }
        for e in adjacency.get(cur, []) {
            if len(edge_type) > 0 and str(e["edge_type"]) not in edge_type {
                continue;
            }
            if n_edges >= edge_limit {
                break;
            }
            n_edges = n_edges + 1;
            tgt = str(e["to"]);
            connections.append((cur, tgt));
            if tgt not in node_depths {
                node_depths[tgt] = cur_depth + 1;
            }
            frontier.append(tgt);
        }
    }
    return {"visited": visited, "connections": connections, "depths": node_depths};
}

"""Generate a storage key for an anchor id."""
def storage_key(anchor_id: str) -> str {
    return "anchor:" + anchor_id;
}

def to_id(value: any) -> str {
    return str(value);
}

"""Project name from a jac.toml sibling of *target_path*; "" when absent."""
def get_name(target_path: str) -> str {
    d = os.path.dirname(target_path);
    if os.path.exists(os.path.join(d, "jac.toml")) {
        return os.path.basename(d);
    }
    return "";
}

"""Database path: projects get project-name.db, standalone files filename.db."""
def get_db_path(base_path: str, target_path: str) -> str {
    name = get_name(target_path);
    if name == "" {
        base = os.path.basename(target_path);
        if "." in base {
            name = base.split(".")[0];
        } else {
            name = base;
        }
    }
    if name == "" {
        return "";
    }
    return os.path.join(base_path, ".jac", "data", name + ".db");
}

