def add_symbol(sid: str, name: str, sym_type: str, decl: tuple, defns: list[tuple], uses: list[tuple]) -> None {
    scope_names[sid][name] = {
        "type": sym_type, "decl": decl, "defns": defns, "uses": uses, "imported": False
    };
}

def symbol_str(sym: dict) -> str {
    decl = sym["decl"];
    return str(sym["type"]) + " decl " + str(decl[0]) + ":" + str(decl[1]);
}

"""Lookup a name in a scope and (optionally) all nested scopes, stack-wise."""
def look_down(sid: str, name: str, deep: bool = True) -> dict {
    if name in scope_names[sid] {
        return scope_names[sid][name];
    }
    if deep {
        stack: list[str] = list(scope_kids.get(sid, []));
        while len(stack) > 0 {
            cur = stack.pop();
            if name in scope_names[cur] {
                return scope_names[cur][name];
            }
            for kid in scope_kids.get(cur, []) {
                stack.append(kid);
            }
        }
    }
    return {};
}

